-- ============================================================
--  VERIFICATION
-- ============================================================
SELECT 'parks' AS tbl, COUNT(*) AS n FROM parks
UNION ALL SELECT 'users',COUNT(*) FROM users
UNION ALL SELECT 'visitors',COUNT(*) FROM visitors
UNION ALL SELECT 'subscribers',COUNT(*) FROM subscribers
UNION ALL SELECT 'guides',COUNT(*) FROM guides
UNION ALL SELECT 'orders',COUNT(*) FROM orders
UNION ALL SELECT 'orders_completed',COUNT(*) FROM orders WHERE status='completed'
UNION ALL SELECT 'orders_confirmed',COUNT(*) FROM orders WHERE status='confirmed'
UNION ALL SELECT 'orders_cancelled',COUNT(*) FROM orders WHERE status='cancelled'
UNION ALL SELECT 'orders_no_show',COUNT(*) FROM orders WHERE status='no_show'
UNION ALL SELECT 'waiting_list',COUNT(*) FROM waiting_list
UNION ALL SELECT 'promotions',COUNT(*) FROM promotions
UNION ALL SELECT 'park_settings_requests',COUNT(*) FROM park_settings_requests;

SELECT SUM(num_visitors) AS yosemite_jul03_confirmed
FROM orders WHERE park_id=1 AND visit_date='2026-07-03' AND status='confirmed';

-- Usage-report preview: avg visitors per operating day, by hour, per park
-- (April; the same shape the line chart plots). Peaks at each park's peak hour.
SELECT p.name AS park, TIME_FORMAT(o.visit_time,'%H:00') AS hour,
       ROUND(SUM(o.num_visitors)/d.day_count,1) AS avg_per_day,
       ROUND(SUM(o.num_visitors)/d.day_count/p.capacity*100,1) AS pct_capacity
FROM orders o JOIN parks p ON p.id=o.park_id
JOIN (SELECT park_id, COUNT(DISTINCT visit_date) AS day_count FROM orders
      WHERE status='completed' AND entry_time IS NOT NULL AND exit_time IS NOT NULL
        AND YEAR(visit_date)=2026 AND MONTH(visit_date)=4 GROUP BY park_id) d
  ON d.park_id=p.id
WHERE o.status='completed' AND o.entry_time IS NOT NULL AND o.exit_time IS NOT NULL
  AND YEAR(o.visit_date)=2026 AND MONTH(o.visit_date)=4
GROUP BY p.id, p.name, p.capacity, hour, d.day_count
ORDER BY p.name, hour;

-- Mark past orders as already reminded so a fresh server start does not
-- re-send reminders for visits that have already occurred.
UPDATE orders SET reminder_sent = 1 WHERE status IN ('completed', 'no_show', 'cancelled');
